      cancel: async () => {
        stops++;
        return result;
      },
      releaseRaw: async () => ({ released: true }),
    };
    const original = (app as any).store,
      save = original.save.bind(original);
    original.save = async (state: WorkspaceState) => {
      entered.resolve();
      await resume.promise;
