test("withdrawal fences an in-flight consent against both a late receipt and a late retryable failure", async () => {
  for (const failure of [false, true]) {
    const payload = {
      invitation_id: randomUUID(),
      document_version: "v1",
      document_sha256: "a".repeat(64),
      accepted: true,
      acknowledged_at: at,
    };
    let state = queueMutation(
      emptyWorkspace("local:account", at),
      "consent",
      { study_id: "unit-study", payload },
      randomUUID,
      at,
    );
    const id = state.queue[0]!.id,
      entered = deferred<void>(),
      reply = deferred<ApiResponse<unknown>>();
    let calls = 0;
    const api = {
      request: async () => {
        calls++;
        entered.resolve();
        return reply.promise;
      },
    } as unknown as ApiClient;
    const engine = new SyncEngine(
      api,
      () => state,
      async (change) => {
        state = change(state);
      },
      () => "same-workspace",
      () => true,
    );
    const pending = engine.run(id, true);
    await entered.promise;
    state = clone(state);
    state.queue[0]!.state = "blocked";
    state.queue[0]!.error = "WITHDRAWAL_PENDING";
    if (failure)
      reply.reject(
        new ApiError(0, "REQUEST_CANCELED", "Canceled for withdrawal", true),
      );
    else
      reply.resolve({
        value: {
          ...payload,
          study_id: "unit-study",
          consent_record_id: randomUUID(),
          state: "active",
          accepted_at: at,
        },
        status: 201,
        etag: null,
        evidenceSha256: null,
      });
    await pending;
    await engine.retryDue(true);
    assert.equal(state.queue[0]!.state, "blocked");
    assert.equal(state.queue[0]!.error, "WITHDRAWAL_PENDING");
    assert.equal(calls, 1);
  }
});
function seeded() {
  let state = emptyWorkspace("local:account", at);
  let check = createCheck(state, {
    now: at,
    id: randomUUID,
    kind: "engineering_fixture",
    accountRef: "00000000-0000-4000-8000-000000000001",
    contextConfirmed: true,
  });
  check = simulatedCapture(check, "saliva", at, randomUUID);
  check = freezeCheck(check, at, randomUUID);
  state = replaceCheck(state, check);
  return { state, check };
}
interface Call {
  path: string;
  options: Record<string, unknown>;
}
function harness(
  initial: WorkspaceState,
  options: {
    lostRegistration?: boolean;
    failStatus?: number;
    deletion?: boolean;
  } = {},
) {
  let state = clone(initial),
    lost = false,
    epoch = "owner-epoch-1",
    available = true;
  const calls: Call[] = [];
  const fake = {
    async request(
      path: string,
      input: Record<string, unknown> = {},
    ): Promise<ApiResponse<unknown>> {
      calls.push({ path, options: clone(input) });
      if (options.failStatus)
        throw new ApiError(
          options.failStatus,
          "TEST_FAILURE",
          "Request rejected",
        );
      if (path === "/v1/privacy/deletion-requests")
        return {
          value: {
            schema_version: "1.0.0",
            kind: "deletion",
            job_id: "88888888-8888-4888-8888-888888888888",
            scope: "all_data",
            data_generation: 2,
            state: "pending",
            accepted_at: at,
            retained_categories: [],
            policy_version: "privacy-v1",
            attempt_count: 0,
            allowed_actions: ["refresh"],
          },
          status: 202,
          etag: null,
          evidenceSha256: null,
        };
      const check = state.checks[0]!;
      if (path === "/v1/sessions" && options.lostRegistration && !lost) {
        lost = true;
        throw new ApiError(
          0,
          "LOST_REPLY",
          "The service accepted the request but its response was lost.",
          true,
        );
      }
      const value = path.endsWith("/snapshot")
        ? { revision: 2, snapshot_sha256: check.snapshot_sha256 }
        : path.endsWith("/result")
          ? check.result
          : { revision: 1 };
      return {
        value,
        status: path.endsWith("/finalize") ? 202 : 200,
        etag: path.endsWith("/snapshot") ? '"2"' : '"1"',
        evidenceSha256: check.evidence_sha256,
      };
    },
  };
  const engine = new SyncEngine(
    fake as unknown as ApiClient,
    () => state,
    async (change) => {
      state = change(state);
    },
    () => epoch,
    () => available,
  );
  return {
    engine,
    calls,
    get state() {
      return state;
    },
    set state(value: WorkspaceState) {
      state = value;
    },
    changeEpoch() {
      epoch = "new-owner";
    },
    pause() {
      available = false;
    },
  };
}

