    const entered = deferred<void>(),
      reply = deferred<Response>();
    service.overrides.set("/oauth2/token", () => {
      entered.resolve();
      return reply.promise;
    });
    const old = auth.accessToken();
    await entered.promise;
    const next = {
      ...identity,
      accountRef: "00000000-0000-4000-8000-000000000002",
