    await auth.commit(
      { ...tokens, accessToken: "account-B", refreshToken: "refresh-B" },
      next,
    );
    const rejected = assert.rejects(() => old, { code: "AUTH_CHANGED" });
    reply.resolve(
      service.result({
        access_token: "old-A",
        token_type: "Bearer",
        expires_in: 900,
      }),
    );
    await rejected;
    assert.equal(await auth.accessToken(), "account-B");
