    assert.throws(() =>
      verifyCaptureGrant(
        changed,
        check,
        grant.attempt_id,
        "task",
        config,
        null,
        null,
      ),
    );
  }
  assert.throws(() =>
    verifyCaptureStart(
      { ...fixture.start, device_boot_id: randomUUID() },
      accepted,
      grant.attempt_id,
      fixture.start.device_boot_id,
