      await auth.clear();
      service.calls.length = 0;
      const path = new URL(config.auth[endpoint]!).pathname;
      for (const target of [
        "https://foreign.invalid" + path,
        "http://localhost:8089" + path,
        "http://localhost:8081" + path + "/extra",
